import{_ as a,a as t}from"./chunks/OpenMQTTGateway_Home_Assistant_MQTT_discovery.mSTvsZ93.js";import{_ as i,o as s,c as n,a6 as o}from"./chunks/framework.BJFjZBwW.js";const m=JSON.parse('{"title":"Advanced configuration of the gateway","description":"","frontmatter":{},"headers":[],"relativePath":"upload/advanced-configuration.md","filePath":"upload/advanced-configuration.md","lastUpdated":1716215449000}'),r={name:"upload/advanced-configuration.md"};function c(d,e,p,l,u,h){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="advanced-configuration-of-the-gateway" tabindex="-1">Advanced configuration of the gateway <a class="header-anchor" href="#advanced-configuration-of-the-gateway" aria-label="Permalink to &quot;Advanced configuration of the gateway&quot;">​</a></h1><h2 id="secure-connection-to-the-broker" tabindex="-1">Secure connection to the broker <a class="header-anchor" href="#secure-connection-to-the-broker" aria-label="Permalink to &quot;Secure connection to the broker&quot;">​</a></h2><p>By default the connection between the gateway and the MQTT broker is not encrypted and the identity of the broker is not verified. For connections in a private local area network this might not be a big issue, but if you connect to a broker on the internet or the gateway is connected to a public network there is a high security risk.</p><p>To secure the connection, Transport Layer Security (TLS) can be used which is supported by most MQTT brokers. Setting up and configuring TLS in the MQTT broker is a complex process and perhaps include creating a self-signed certificate. The configuration of the broker is not covered here, you should look into the documentation of your broker.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>The MQTT broker is configured for TLS and you have access to the CA certificate which was used to sign the MQTT broker certificate. You are using ESP8266 or ESP32.</p><h3 id="configure-secure-connection-in-the-gateway" tabindex="-1">Configure secure connection in the gateway <a class="header-anchor" href="#configure-secure-connection-in-the-gateway" aria-label="Permalink to &quot;Configure secure connection in the gateway&quot;">​</a></h3><p>To enable the secure connection and use TLS set the <code>#define MQTT_DEFAULT_SECURE</code> to true at build time, or the <code>mqtt secure</code> parameter with WiFi Manager or <code>mqtt_secure</code> with MQTT. Set <code>MQTT_SERVER</code> to the Common Name (CN) of the certificate of the broker.</p><p>The server identity can be verified against a certificate or not, if you don&#39;t want to use a certicate to verify the server you can uncheck the option <code>validate cert</code> with WiFi Manager or set <code>mqtt_validate</code> to <code>false</code> with MQTT</p><p>The CA certificate should be in PEM ascii format. If your CA certificate is not in the correct format or you don&#39;t know the format, use <code>openssl</code> to convert the certificate to the correct format. At build time, in <code>main/certs/default_server_cert.h</code> replace the <code>...</code> with the content of your certificate which is between the <code>-----BEGIN CERTIFICATE-----</code> and <code>-----END CERTIFICATE-----</code> lines:</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> certificate CERT_ATTRIBUTE </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> R&quot;EOF(&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-----BEGIN CERTIFICATE-----</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-----END CERTIFICATE-----</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;)EOF&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>With WiFi Manager copy your certificate from <code>-----BEGIN CERTIFICATE-----</code> to <code>-----END CERTIFICATE-----</code> (included) and paste it into the input field:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----BEGIN CERTIFICATE-----</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>-----END CERTIFICATE-----</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>This process can also be used for the other certificates, OTA, client key, client certificate if necessary.</p><h2 id="add-the-received-value-at-the-end-of-the-topic" tabindex="-1">Add the received &quot;value&quot; at the end of the topic <a class="header-anchor" href="#add-the-received-value-at-the-end-of-the-topic" aria-label="Permalink to &quot;Add the received &quot;value&quot; at the end of the topic&quot;">​</a></h2><p>For the gateways that publish a &quot;value&quot; parameter on the json (RF, IR...), it is possible to concatenate this parameter at the end of the topic. So as to activate this function you need to set <code>valueAsATopic</code> to true in User_config.h</p><div class="language-cpp vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#ifndef</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> valueAsATopic</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#  define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> valueAsATopic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // define true to integrate msg value into the subject when receiving</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#endif</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Per default you see the following data:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>home/OpenMQTTGateway/SRFBtoMQTT {&quot;raw&quot;:&quot;2B660186042E00E7E5&quot;,&quot;value&quot;:&quot;59365&quot;,&quot;delay&quot;:&quot;1111&quot;,&quot;val_Thigh&quot;:&quot;390&quot;,&quot;val_Tlow&quot;:&quot;1070&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>With the line uncommented you will see:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>home/OpenMQTTGateway/SRFBtoMQTT/59365 {&quot;raw&quot;:&quot;2B660186042E00E7E5&quot;,&quot;value&quot;:&quot;59365&quot;,&quot;delay&quot;:&quot;1111&quot;,&quot;val_Thigh&quot;:&quot;390&quot;,&quot;val_Tlow&quot;:&quot;1070&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>It can be useful to avoid warning or errors on certain controllers.</p><h2 id="auto-discovery" tabindex="-1">Auto discovery <a class="header-anchor" href="#auto-discovery" aria-label="Permalink to &quot;Auto discovery&quot;">​</a></h2><p>Home Assistant discovery is enabled by default on all binaries and platformio configurations.</p><p>To have a working discovery setup you need to enable it on your MQTT integration definition in HASS.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>With platformio you can deactivate discovery by adding:</p><div class="language-ini vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;-UZmqttDiscovery=&quot;HADiscovery&quot;&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>To your environment definition.</p></div><p>So as to create the MQTT username and password, you have to create a new user(recommended) into Home Assistant-&gt;Configuration-&gt;Users (available in admin mode) or use an existing username/pwd combination (not recommended). This user doesn&#39;t need to be an administrator.</p><p><img src="`+a+'" alt="MQTT User"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The max size of the username is 30 and 60 for the password.</p></div><p>OMG will use the auto discovery functionality of home assistant to create sensors and gateways into your HASS instance automatically.</p><p>The gateway device will be available into Configuration-&gt;Devices section of Home Assistant.</p><p><img src="'+t+'" alt="MQTT Device settings"></p>',32)])])}const v=i(r,[["render",c]]);export{m as __pageData,v as default};
